<script setup lang="ts">
import {computed,nextTick,onMounted,reactive,ref,watch,type Component} from 'vue';
import {RouterLink,useRoute} from 'vue-router';
import {ArrowLeft,ArrowRight,Check,CheckCircle2,ChevronLeft,CircleHelp,ClipboardList,CreditCard,FileCheck2,Headphones,Info,Luggage,Plane,PlaneTakeoff,Plus,ReceiptText,ShieldCheck,Trash2,UserRound,WalletCards} from '@lucide/vue';
import {reportCategories as categories,categoryLabel,companyTypes} from '../../shared/catalog';
import type {Category,ReportInput} from '../../shared/types';
import {reportSchema,validateDynamicAnswers} from '../../shared/validation';
import {api} from '../lib/api';
import {emulatorMode} from '../lib/firebase';
import {normalizeDynamicAnswers,prepareReportPayload,questionsForCategories} from '../lib/form-values';
import ReportField from '../components/report/ReportField.vue';
import BooleanField from '../components/report/BooleanField.vue';
import '../components/report/report.css';

type PublicConfig={mode:'emulator'|'firebase';emailConfigured:boolean};
type SubmitResult={reference:string;mode:'emulator'|'firebase';emailSent:boolean};
const steps=[
  {title:'סוג האירוע',short:'מה קרה',description:'בחרו את הנושא המרכזי של הדיווח שלכם.',help:'גם אם המקרה שלכם נוגע לכמה נושאים, בחרו נושא עיקרי. אפשר להוסיף סיווגים נוספים.'},
  {title:'העסקה והחברות',short:'פרטי העסקה',description:'מי מעורב ומתי התרחש האירוע?',help:'מעורבים כמה ספקים? הוסיפו את החברות המעורבות ובחרו את סוג הספק. מספר הזמנה ופרטי טיסה הם רשות.'},
  {title:'תיאור המקרה',short:'הסיפור שלכם',description:'ספרו במילים שלכם מה קרה ואיך המקרה השפיע עליכם.',help:'תיאור ממוקד לפי סדר האירועים יעזור להבין את המקרה. הפרידו בין סכומים ששילמתם, החזר שביקשתם ונזק נטען.'},
  {title:'פרטים נוספים',short:'שאלות ממוקדות',description:'שאלות בהתאם לנושאים שבחרתם.',help:'אין צורך לנחש. אפשר להשאיר שאלות רשות ללא תשובה אם הפרט אינו ידוע לכם. המועדים לפי זמן ישראל.'},
  {title:'פרטי המדווח',short:'פרטים ליצירת קשר',description:'כיצד נוכל לזהות את הדיווח וליצור קשר לפי הצורך?',help:'פרטי הקשר אינם מתפרסמים לציבור. אין צורך במספר זהות. בדיווח עבור אדם אחר הסבירו את הקשר שלכם לאירוע.'},
  {title:'בדיקה ושליחה',short:'סיכום והסכמות',description:'ודאו שהפרטים נכונים וקראו את ההסכמות לפני השליחה.',help:'הדיווח ללא עלות. הגשתו אינה יוצרת יחסי עורך דין–לקוח ואינה מבטיחה טיפול אישי, ייצוג או פיצוי.'},
];
const fieldsByStep=[['primaryCategory','secondaryCategories'],['companies','bookingChannel','intermediaryName','bookingDate','incidentDate','bookingReference','passengerCount','flight'],['description','companyContacted','companyContactDate','companyResponse','resolved','resolution','purchaseAmount','extraChargeAmount','requestedRefundAmount','receivedRefundAmount','additionalClaimedLoss','currency'],['dynamicAnswers'],['reporter'],['consents']];
const categoryIcons:Record<Category,Component>={cancellation:Plane,delay:PlaneTakeoff,refund:WalletCards,baggage:Luggage,extra_charge:CreditCard,misleading:ReceiptText,booking:FileCheck2,agency:UserRound,package:Luggage,service:Headphones,other:CircleHelp};
const paidFields=[{name:'purchaseAmount',label:'סכום העסקה ששולם'},{name:'extraChargeAmount',label:'סכום נוסף שנגבה'},{name:'receivedRefundAmount',label:'החזר שהתקבל בפועל'}] as const;
const claimedFields=[{name:'requestedRefundAmount',label:'סכום ההחזר שהתבקש'},{name:'additionalClaimedLoss',label:'נזק כספי נטען נוסף'}] as const;
type MoneyField=typeof paidFields[number]['name']|typeof claimedFields[number]['name'];
const flightFields=[{name:'flightNumber',label:'מספר טיסה',placeholder:'למשל AB123'},{name:'originAirport',label:'שדה תעופה מוצא',placeholder:'שם השדה או קוד IATA'},{name:'destinationAirport',label:'שדה תעופה יעד',placeholder:'שם השדה או קוד IATA'}] as const;
const flightTimes=[{name:'scheduledDeparture',label:'מועד המראה מתוכנן'},{name:'actualDeparture',label:'מועד המראה בפועל'},{name:'scheduledArrival',label:'מועד נחיתה מתוכנן'},{name:'actualArrival',label:'מועד נחיתה בפועל'}] as const;
const route=useRoute();
const values=reactive<ReportInput>({primaryCategory:'' as Category,secondaryCategories:[],companies:[{name:'',companyType:'airline'}],bookingChannel:'direct',bookingDate:'',incidentDate:'',bookingReference:'',passengerCount:1,flight:{flightNumber:'',originAirport:'',destinationAirport:'',scheduledDeparture:'',actualDeparture:'',scheduledArrival:'',actualArrival:''},description:'',companyContacted:false,companyContactDate:'',companyResponse:'',resolved:false,resolution:'',currency:'ILS',dynamicAnswers:{},reporter:{fullName:'',email:'',phone:'',isPassenger:true,relationship:''},consents:{privacy:false,caseContact:false,updates:false},honeypot:'',startedAt:Date.now(),idempotencyKey:crypto.randomUUID()});
const step=ref(0),furthestStep=ref(0),config=ref<PublicConfig|null>(null),configError=ref(false),serverError=ref(''),submitting=ref(false),result=ref<SubmitResult|null>(null),copied=ref(false);
const heading=ref<HTMLHeadingElement|null>(null),formElement=ref<HTMLFormElement|null>(null);
const errors=ref<Record<string,string>>({});
const activeQuestions=computed(()=>questionsForCategories(values.primaryCategory,values.secondaryCategories));
const secondaryOptions=computed(()=>categories.filter(category=>category.id!==values.primaryCategory));
const currentStep=computed(()=>steps[step.value]!);
const isEmulator=computed(()=>emulatorMode||config.value?.mode==='emulator');
const reportedMoney=computed(()=>[...paidFields,...claimedFields].filter(field=>values[field.name]!==undefined).map(field=>({label:field.label,value:new Intl.NumberFormat('he-IL',{maximumFractionDigits:2}).format(values[field.name]!)})));
const answeredQuestions=computed(()=>activeQuestions.value.filter(question=>values.dynamicAnswers[question.key]!==undefined&&values.dynamicAnswers[question.key]!=='').map(question=>({label:question.label,value:typeof values.dynamicAnswers[question.key]==='boolean'?(values.dynamicAnswers[question.key]?'כן':'לא'):String(values.dynamicAnswers[question.key])})));
const errorAt=(name:string)=>errors.value[name];
const attrs=(name:string)=>({id:name,'aria-invalid':!!errorAt(name),'aria-describedby':errorAt(name)?`${name}-error`:undefined});
function friendlyError(name:string,message:string){
  if(/[\u0590-\u05ff]/.test(message))return message;
  if(name==='primaryCategory')return 'בחרו את סוג האירוע העיקרי.';
  if(name==='passengerCount')return 'הזינו מספר שלם של נוסעים או צרכנים, בין 1 ל-10,000.';
  if([...paidFields,...claimedFields].some(field=>field.name===name))return 'הזינו סכום שאינו שלילי, עם עד שתי ספרות אחרי הנקודה.';
  return 'הערך שהוזן אינו תקין. בדקו את השדה ונסו שוב.';
}
async function loadConfig(){
  configError.value=false;
  try{config.value=await api<PublicConfig>('/api/config');}catch{configError.value=true;}
}
onMounted(()=>{void loadConfig();const category=String(route.query.category??'');if(categories.some(item=>item.id===category))values.primaryCategory=category as Category;});
watch(()=>values.primaryCategory,primary=>{values.secondaryCategories=values.secondaryCategories.filter(category=>category!==primary);});
watch(activeQuestions,questions=>{const keys=new Set(questions.map(question=>question.key));values.dynamicAnswers=Object.fromEntries(Object.entries(values.dynamicAnswers).filter(([key])=>keys.has(key)));});
watch(step,async()=>{await nextTick();heading.value?.focus({preventScroll:true});document.getElementById('report-start')?.scrollIntoView({behavior:'smooth',block:'start'});});
function goTo(index:number){if(submitting.value||index>furthestStep.value)return;step.value=index;serverError.value='';}
function normalizeDraft(){return prepareReportPayload({...values,dynamicAnswers:normalizeDynamicAnswers(values.dynamicAnswers)});}
function collectErrors(){
  const checked=reportSchema.safeParse(normalizeDraft());
  const found:Record<string,string>={};
  if(!checked.success)for(const issue of checked.error.issues){const path=issue.path.join('.');if(!found[path])found[path]=friendlyError(path,issue.message);}
  return found;
}
async function focusError(){await nextTick();formElement.value?.querySelector<HTMLElement>('[aria-invalid="true"]')?.focus();}
async function next(){
  const allErrors=collectErrors();const paths=fieldsByStep[step.value]??[];
  const currentErrors=Object.fromEntries(Object.entries(allErrors).filter(([name])=>paths.some(path=>name===path||name.startsWith(`${path}.`))));
  if(step.value===3){const dynamicErrors=validateDynamicAnswers(values.primaryCategory,values.secondaryCategories,normalizeDynamicAnswers(values.dynamicAnswers));for(const [name,messages]of Object.entries(dynamicErrors))currentErrors[name]=messages[0]!;}
  errors.value=currentErrors;
  if(Object.keys(currentErrors).length){await focusError();return;}
  step.value=Math.min(step.value+1,steps.length-1);furthestStep.value=Math.max(furthestStep.value,step.value);serverError.value='';
}
function setMoney(name:MoneyField,event:Event){const raw=(event.target as HTMLInputElement).value;values[name]=raw===''?undefined:Number(raw);}
function dynamicValue(key:string){const value=values.dynamicAnswers[key];return value===undefined?'':String(value);}
function setDynamic(key:string,type:string,event:Event){
  const raw=(event.target as HTMLInputElement).value;
  if(raw===''){delete values.dynamicAnswers[key];return;}
  values.dynamicAnswers[key]=type==='boolean'?raw==='true':type==='number'?Number(raw):raw;
}
async function submit(){
  if(step.value<steps.length-1){await next();return;}
  if(submitting.value||!config.value)return;
  errors.value=collectErrors();
  if(Object.keys(errors.value).length){const names=Object.keys(errors.value);const invalidStep=fieldsByStep.findIndex(paths=>names.some(name=>paths.some(path=>name===path||name.startsWith(`${path}.`))));if(invalidStep>=0)step.value=invalidStep;serverError.value='יש להשלים או לתקן את השדות המסומנים לפני השליחה.';await focusError();return;}
  submitting.value=true;serverError.value='';
  try{
    const formData=new FormData();formData.append('payload',JSON.stringify(normalizeDraft()));
    result.value=await api<SubmitResult>('/api/reports',{method:'POST',body:formData});window.scrollTo({top:0,behavior:'smooth'});
  }catch(error){
    const failure=error as Error&{fieldErrors?:Record<string,string[]>;data?:{fieldErrors?:Record<string,string[]>}};
    const fieldErrors=failure.fieldErrors??failure.data?.fieldErrors;
    if(fieldErrors){errors.value=Object.fromEntries(Object.entries(fieldErrors).map(([key,messages])=>[key,messages.join(' ')]));const invalidStep=fieldsByStep.findIndex(paths=>Object.keys(fieldErrors).some(name=>paths.some(path=>name===path||name.startsWith(`${path}.`))));if(invalidStep>=0)step.value=invalidStep;await focusError();}
    serverError.value=failure.message||'לא הצלחנו להתחבר לשרת. הפרטים נשארו בטופס; אפשר לנסות שוב.';
  }finally{submitting.value=false;}
}
async function copyReference(){if(!result.value)return;try{await navigator.clipboard.writeText(result.value.reference);copied.value=true;}catch{copied.value=false;}}
</script>

<template>
  <main v-if="result" id="main-content" class="report-page report-success">
    <div class="report-success-icon"><CheckCircle2 :size="38" /></div><span class="eyebrow">הדיווח התקבל</span><h1>תודה שהשמעתם את הקול שלכם.</h1>
    <p class="report-success-lead">הדיווח נשמר במערכת ויהיה זמין לבדיקה למנהלים המורשים.</p>
    <div class="report-reference card"><span>מספר הדיווח שלכם</span><strong dir="ltr">{{ result.reference }}</strong><button type="button" class="btn btn-secondary" @click="copyReference">{{ copied?'המספר הועתק':'העתקת מספר הדיווח' }}</button><small>שמרו את המספר לפנייה עתידית.</small></div>
    <div v-if="isEmulator" class="report-notice"><Info :size="20" /><p><strong>זהו דיווח בדיקה מקומי.</strong> הפרטים הפיקטיביים נשמרו באמולטור Firestore במחשב הזה.</p></div>
    <p>{{ result.emailSent?'אישור קבלה נשלח לכתובת הדוא״ל שמסרתם.':'אישור בדוא״ל לא נשלח. שמרו את מספר הדיווח המוצג כאן.' }}</p>
    <div class="report-success-next"><h2>מה קורה עכשיו?</h2><p>המידע מסייע בבחינת דיווחים ובאיתור דפוסים חוזרים. הגשתו אינה מבטיחה טיפול אישי, ייצוג משפטי או פיצוי. הדיווח ופרטי הקשר אינם מתפרסמים אוטומטית.</p></div>
    <RouterLink to="/" class="btn btn-primary">חזרה לעמוד הראשי<ArrowLeft :size="18" /></RouterLink>
  </main>
  <main v-else id="main-content" class="report-page">
    <div class="report-intro"><div class="report-breadcrumb"><RouterLink to="/">ראשי</RouterLink><ChevronLeft :size="14" /><span>דיווח על פגיעה</span></div><div class="report-intro-line"><div><span class="eyebrow">הקול שלכם. הזכויות של כולנו.</span><h1>המקרה שלכם יכול לעשות שינוי.</h1><p>משתפים במה שקרה. מתחברים לכוח שפועל למען הצרכנים.</p></div><span class="report-trust"><ShieldCheck :size="19" />הדיווח ללא עלות</span></div></div>
    <div id="report-start" class="report-layout">
      <aside class="report-sidebar" aria-label="שלבי הטופס"><div class="report-progress-caption"><span>הדיווח שלכם</span><span aria-live="polite">שלב {{ step+1 }} מתוך {{ steps.length }}</span></div><div class="report-progress" role="progressbar" aria-label="התקדמות הטופס" :aria-valuemin="1" :aria-valuemax="steps.length" :aria-valuenow="step+1"><span :style="{width:`${(step+1)/steps.length*100}%`}" /></div><ol class="report-steps"><li v-for="(item,index) in steps" :key="item.title" :class="{active:index===step,complete:index<step}"><button type="button" :disabled="index>furthestStep||submitting" :aria-current="index===step?'step':undefined" @click="goTo(index)"><span class="report-step-number"><Check v-if="index<step" :size="15" /><template v-else>{{ index+1 }}</template></span><span><strong>{{ item.title }}</strong><small>{{ item.short }}</small></span><span v-if="index===step" class="report-step-dot" /></button></li></ol><div class="report-sidebar-note"><ShieldCheck :size="21" /><p>המידע שלכם אינו מתפרסם לציבור.<br /><RouterLink to="/privacy">למדיניות הפרטיות<ArrowLeft :size="13" /></RouterLink></p></div></aside>
      <div class="report-form-column">
        <div v-if="isEmulator" class="report-notice report-demo" role="status"><Info :size="19" /><p><strong>בדיקה מקומית · השתמשו בפרטים פיקטיביים בלבד.</strong> הדיווח נשמר באמולטור Firestore. אל תמסרו מידע אישי אמיתי.</p></div>
        <div v-if="configError" class="report-alert" role="alert">לא ניתן לטעון את הגדרות המערכת. <button type="button" @click="loadConfig">ניסיון נוסף</button></div>
        <form ref="formElement" class="report-form card" novalidate @submit.prevent="submit">
          <div class="report-form-header"><span class="report-step-kicker">שלב {{ String(step+1).padStart(2,'0') }} / {{ String(steps.length).padStart(2,'0') }}</span><h2 ref="heading" tabindex="-1">{{ step===0?'על מה תרצו לדווח?':currentStep.title }}</h2><p>{{ currentStep.description }}</p><span class="report-required-note">שדות ללא סימון „רשות” נדרשים להשלמת הדיווח.</span></div>
          <div class="report-honeypot" aria-hidden="true"><label for="website">השאירו שדה זה ריק</label><input id="website" v-model="values.honeypot" tabindex="-1" autocomplete="off" /></div>
          <div v-if="serverError" class="report-alert" role="alert">{{ serverError }}</div>
          <div class="report-step-content">
            <template v-if="step===0">
              <fieldset class="report-category-fieldset"><legend class="sr-only">בחרו קטגוריה ראשית</legend><div class="report-categories"><label v-for="category in categories" :key="category.id" class="report-category" :class="{selected:values.primaryCategory===category.id}"><input v-model="values.primaryCategory" type="radio" name="primaryCategory" :value="category.id" :aria-invalid="!!errorAt('primaryCategory')" :aria-describedby="errorAt('primaryCategory')?'primaryCategory-error':undefined" /><span class="report-category-icon"><component :is="categoryIcons[category.id]" :size="22" /></span><span>{{ category.label }}</span><span class="report-category-check"><Check v-if="values.primaryCategory===category.id" :size="11" /></span></label></div></fieldset>
              <p v-if="errorAt('primaryCategory')" id="primaryCategory-error" class="field-error" role="alert">{{ errorAt('primaryCategory') }}</p>
              <div class="report-secondary"><h3>האם היו גם נושאים נוספים? <span class="report-optional">רשות</span></h3><p>אפשר לבחור כמה נושאים נוספים המתאימים לאותו מקרה.</p><div class="report-chips"><label v-for="category in secondaryOptions" :key="category.id" :class="{selected:values.secondaryCategories.includes(category.id)}"><input v-model="values.secondaryCategories" type="checkbox" :value="category.id" />{{ category.short }}</label></div><p v-if="errorAt('secondaryCategories')" class="field-error" role="alert">{{ errorAt('secondaryCategories') }}</p></div>
            </template>
            <template v-else-if="step===1">
              <section class="report-section"><div class="report-section-heading"><h3>החברות והספקים המעורבים</h3><span>אפשר להוסיף עד 8 ספקים</span></div><div v-for="(company,index) in values.companies" :key="index" class="report-company"><div class="report-company-heading"><span>ספק {{ index+1 }}</span><button v-if="index>0" class="report-icon-button" type="button" :aria-label="`הסרת ספק ${index+1}`" @click="values.companies.splice(index,1)"><Trash2 :size="16" /></button></div><div class="form-grid"><ReportField :name="`companies.${index}.name`" label="שם החברה או הספק" :error="errorAt(`companies.${index}.name`)"><input v-bind="attrs(`companies.${index}.name`)" v-model="company.name" class="input" maxlength="200" placeholder="חברת התעופה או סוכנות הנסיעות" /></ReportField><ReportField :name="`companies.${index}.companyType`" label="סוג הספק" :error="errorAt(`companies.${index}.companyType`)"><select v-bind="attrs(`companies.${index}.companyType`)" v-model="company.companyType" class="select"><option v-for="type in companyTypes" :key="type.id" :value="type.id">{{ type.label }}</option></select></ReportField></div></div><p v-if="errorAt('companies')" class="field-error" role="alert">{{ errorAt('companies') }}</p><button type="button" class="btn btn-secondary report-add-company" :disabled="values.companies.length>=8" @click="values.companies.push({name:'',companyType:'agency'})"><Plus :size="17" />הוספת חברה או ספק</button></section>
              <section class="report-section"><h3>פרטי ההזמנה</h3><ReportField name="bookingChannel" label="באמצעות מי בוצעה ההזמנה?" :error="errorAt('bookingChannel')"><select v-bind="attrs('bookingChannel')" v-model="values.bookingChannel" class="select"><option value="direct">ישירות מול הספק</option><option value="intermediary">באמצעות מתווך או סוכנות</option></select></ReportField><ReportField v-if="values.bookingChannel==='intermediary'" name="intermediaryName" label="שם הגורם שבאמצעותו בוצעה ההזמנה" :error="errorAt('intermediaryName')"><input v-bind="attrs('intermediaryName')" v-model="values.intermediaryName" class="input" maxlength="200" /></ReportField><div class="form-grid"><ReportField name="bookingDate" label="תאריך ההזמנה" optional :error="errorAt('bookingDate')"><input v-bind="attrs('bookingDate')" v-model="values.bookingDate" class="input" type="date" /></ReportField><ReportField name="incidentDate" label="תאריך האירוע" :error="errorAt('incidentDate')"><input v-bind="attrs('incidentDate')" v-model="values.incidentDate" class="input" type="date" /></ReportField><ReportField name="bookingReference" label="מספר הזמנה" optional :error="errorAt('bookingReference')"><input v-bind="attrs('bookingReference')" v-model="values.bookingReference" class="input" dir="auto" maxlength="100" /></ReportField><ReportField name="passengerCount" label="מספר הנוסעים או הצרכנים שנפגעו" :error="errorAt('passengerCount')"><input v-bind="attrs('passengerCount')" v-model.number="values.passengerCount" class="input" type="number" min="1" max="10000" inputmode="numeric" /></ReportField></div></section>
              <section class="report-section"><h3><PlaneTakeoff :size="18" />פרטי הטיסה <span class="report-optional">אם רלוונטי · רשות</span></h3><div class="form-grid"><ReportField v-for="field in flightFields" :key="field.name" :name="`flight.${field.name}`" :label="field.label" optional :error="errorAt(`flight.${field.name}`)"><input v-bind="attrs(`flight.${field.name}`)" v-model="values.flight[field.name]" class="input" :dir="field.name==='flightNumber'?'ltr':'auto'" :placeholder="field.placeholder" :maxlength="field.name==='flightNumber'?30:100" /></ReportField></div><details class="report-flight-times"><summary>מועדי המראה ונחיתה · רשות</summary><p class="report-field-help">כל המועדים לפי שעון ישראל. אפשר למסור אותם גם בשאלות הממוקדות בשלב הבא.</p><div class="form-grid"><ReportField v-for="field in flightTimes" :key="field.name" :name="`flight.${field.name}`" :label="field.label" optional :error="errorAt(`flight.${field.name}`)"><input v-bind="attrs(`flight.${field.name}`)" v-model="values.flight[field.name]" class="input" type="datetime-local" /></ReportField></div></details></section>
            </template>
            <template v-else-if="step===2">
              <ReportField name="description" label="מה קרה?" help="תארו את האירוע לפי הסדר. הימנעו מפרטי זיהוי וממידע רגיש שאינם נחוצים." :error="errorAt('description')"><textarea v-bind="attrs('description')" v-model="values.description" class="textarea" rows="6" maxlength="12000" placeholder="למשל: הזמנתי טיסה, ובהמשך קיבלתי הודעה ש..." /><span class="report-character-count">{{ values.description.length.toLocaleString('he-IL') }} / 12,000 · לפחות 20 תווים</span></ReportField>
              <section class="report-section"><h3>הפנייה לחברה ותוצאותיה</h3><BooleanField v-model="values.companyContacted" name="companyContacted" label="האם פניתם לחברה בנושא?" :error="errorAt('companyContacted')" /><div v-if="values.companyContacted" class="report-conditional"><ReportField name="companyContactDate" label="מתי פניתם?" optional :error="errorAt('companyContactDate')"><input v-bind="attrs('companyContactDate')" v-model="values.companyContactDate" type="date" class="input" /></ReportField><ReportField name="companyResponse" label="מה הייתה תגובת החברה?" optional :error="errorAt('companyResponse')"><textarea v-bind="attrs('companyResponse')" v-model="values.companyResponse" class="textarea" rows="3" maxlength="4000" /></ReportField></div><BooleanField v-model="values.resolved" name="resolved" label="האם הבעיה נפתרה?" :error="errorAt('resolved')" /><ReportField v-if="values.resolved" name="resolution" label="איזה החזר, פיצוי או פתרון קיבלתם?" optional :error="errorAt('resolution')"><textarea v-bind="attrs('resolution')" v-model="values.resolution" class="textarea" rows="3" maxlength="4000" /></ReportField></section>
              <section class="report-section"><h3>הסכומים הכספיים <span class="report-optional">רשות</span></h3><p class="report-field-help">מלאו רק סכומים שידועים לכם. השדות נפרדים כדי להבחין בין תשלום, דרישה ונזק נטען.</p><ReportField name="currency" label="מטבע" :error="errorAt('currency')"><select v-bind="attrs('currency')" v-model="values.currency" class="select"><option value="ILS">שקל חדש · ILS</option><option value="USD">דולר ארה״ב · USD</option><option value="EUR">אירו · EUR</option><option value="GBP">ליש״ט · GBP</option><option value="other">אחר</option></select></ReportField><div class="report-money-group"><h4>סכומים ששולמו או התקבלו בפועל</h4><div class="form-grid"><ReportField v-for="field in paidFields" :key="field.name" :name="field.name" :label="field.label" optional :error="errorAt(field.name)"><input v-bind="attrs(field.name)" :value="values[field.name]??''" type="number" class="input" min="0" max="100000000" step="0.01" inputmode="decimal" placeholder="0.00" @input="setMoney(field.name,$event)" /></ReportField></div></div><div class="report-money-group claimed"><h4>סכומים שהתבקשו ונזק נטען</h4><div class="form-grid"><ReportField v-for="field in claimedFields" :key="field.name" :name="field.name" :label="field.label" optional :error="errorAt(field.name)"><input v-bind="attrs(field.name)" :value="values[field.name]??''" type="number" class="input" min="0" max="100000000" step="0.01" inputmode="decimal" placeholder="0.00" @input="setMoney(field.name,$event)" /></ReportField></div></div></section>
            </template>
            <template v-else-if="step===3">
              <template v-if="activeQuestions.length"><div class="report-context-label"><ClipboardList :size="17" />שאלות לפי הנושאים שבחרתם</div><div class="form-grid"><ReportField v-for="question in activeQuestions" :key="question.key" :name="`dynamicAnswers.${question.key}`" :label="question.label" :optional="!question.required" :error="errorAt(`dynamicAnswers.${question.key}`)"><select v-if="question.type==='boolean'" v-bind="attrs(`dynamicAnswers.${question.key}`)" class="select" :value="dynamicValue(question.key)" @change="setDynamic(question.key,question.type,$event)"><option value="">בחרו תשובה</option><option value="true">כן</option><option value="false">לא</option></select><select v-else-if="question.type==='select'" v-bind="attrs(`dynamicAnswers.${question.key}`)" class="select" :value="dynamicValue(question.key)" @change="setDynamic(question.key,question.type,$event)"><option value="">בחרו אפשרות</option><option v-for="option in question.options" :key="option" :value="option">{{ option }}</option></select><input v-else v-bind="attrs(`dynamicAnswers.${question.key}`)" class="input" :type="question.type" :value="dynamicValue(question.key)" :min="question.type==='number'?0:undefined" :step="question.type==='number'?'0.01':undefined" :maxlength="question.type==='text'?2000:undefined" @input="setDynamic(question.key,question.type,$event)" /></ReportField></div><p class="report-field-help">תאריכים ושעות לפי שעון ישראל. אם המועד אינו ידוע, אפשר להשאיר את השדה ריק.</p></template>
              <div v-else class="report-empty-step"><div><CheckCircle2 :size="30" /></div><h3>יש לנו את הפרטים הדרושים לשלב הזה.</h3><p>לנושא שבחרתם אין שאלות נוספות. אפשר להמשיך לפרטי המדווח.</p></div>
            </template>
            <template v-else-if="step===4">
              <div class="report-context-label"><UserRound :size="17" />פרטי המדווח</div><ReportField name="reporter.fullName" label="שם מלא" :error="errorAt('reporter.fullName')"><input v-bind="attrs('reporter.fullName')" v-model="values.reporter.fullName" class="input" autocomplete="name" placeholder="שם פרטי ושם משפחה" maxlength="150" /></ReportField><div class="form-grid"><ReportField name="reporter.email" label="כתובת דוא״ל" :error="errorAt('reporter.email')"><input v-bind="attrs('reporter.email')" v-model="values.reporter.email" class="input" type="email" dir="ltr" autocomplete="email" inputmode="email" placeholder="name@example.com" maxlength="254" /></ReportField><ReportField name="reporter.phone" label="מספר טלפון" :error="errorAt('reporter.phone')"><input v-bind="attrs('reporter.phone')" v-model="values.reporter.phone" class="input" type="tel" dir="ltr" autocomplete="tel" inputmode="tel" placeholder="050-0000000" maxlength="30" /></ReportField></div><BooleanField v-model="values.reporter.isPassenger" name="reporter.isPassenger" label="האם אתם אחד הנוסעים או הצרכנים שנפגעו?" :error="errorAt('reporter.isPassenger')" /><ReportField v-if="!values.reporter.isPassenger" name="reporter.relationship" label="מה הקשר שלכם לאירוע?" :error="errorAt('reporter.relationship')"><textarea v-bind="attrs('reporter.relationship')" v-model="values.reporter.relationship" class="textarea" rows="3" maxlength="200" placeholder="למשל: בן/בת משפחה של אחד הנוסעים" /></ReportField><div class="report-notice"><ShieldCheck :size="20" /><p>אין צורך במספר תעודת זהות. המידע יטופל בהתאם ל<RouterLink to="/privacy" target="_blank" rel="noopener">הודעת הפרטיות</RouterLink>.</p></div>
            </template>
            <template v-else-if="step===5">
              <div class="report-summary"><div class="report-summary-header"><h3>סיכום הדיווח שלכם</h3><span class="badge">לפני השליחה</span></div><dl><div><dt>נושא הדיווח<button type="button" @click="goTo(0)">עריכה</button></dt><dd>{{ categoryLabel(values.primaryCategory) }}<small v-if="values.secondaryCategories.length">{{ values.secondaryCategories.map(categoryLabel).join(' · ') }}</small></dd></div><div><dt>חברות מעורבות<button type="button" @click="goTo(1)">עריכה</button></dt><dd>{{ values.companies.map(company=>company.name).join(' · ') }}<small>תאריך האירוע: {{ values.incidentDate }} · {{ values.passengerCount }} נוסעים / צרכנים</small></dd></div><div><dt>תיאור האירוע<button type="button" @click="goTo(2)">עריכה</button></dt><dd class="report-summary-description">{{ values.description }}</dd></div><div><dt>פרטי המדווח<button type="button" @click="goTo(4)">עריכה</button></dt><dd>{{ values.reporter.fullName }}<small><span dir="ltr">{{ values.reporter.email }}</span> · <span dir="ltr">{{ values.reporter.phone }}</span></small></dd></div></dl></div>
              <details class="report-review-details"><summary>הצגת יתר פרטי הדיווח</summary><dl><div v-for="(company,index) in values.companies" :key="`company-${index}`"><dt>{{ company.name }}</dt><dd>{{ companyTypes.find(type=>type.id===company.companyType)?.label }}</dd></div><div><dt>ההזמנה</dt><dd>{{ values.bookingChannel==='direct'?'ישירות מול הספק':`באמצעות ${values.intermediaryName}` }}<small v-if="values.bookingDate">תאריך הזמנה: {{ values.bookingDate }}</small><small v-if="values.bookingReference">מספר הזמנה: {{ values.bookingReference }}</small></dd></div><div v-for="field in [...flightFields,...flightTimes].filter(field=>values.flight[field.name])" :key="field.name"><dt>{{ field.label }}</dt><dd dir="auto">{{ values.flight[field.name] }}</dd></div><div><dt>פנייה לחברה</dt><dd>{{ values.companyContacted?'פנינו לחברה':'לא פנינו לחברה' }}<small v-if="values.companyContacted&&values.companyContactDate">{{ values.companyContactDate }}</small><small v-if="values.companyContacted&&values.companyResponse">{{ values.companyResponse }}</small></dd></div><div><dt>פתרון הבעיה</dt><dd>{{ values.resolved?'הבעיה נפתרה':'הבעיה טרם נפתרה' }}<small v-if="values.resolved&&values.resolution">{{ values.resolution }}</small></dd></div><div v-for="item in reportedMoney" :key="item.label"><dt>{{ item.label }}</dt><dd>{{ item.value }} {{ values.currency }}</dd></div><div v-for="question in answeredQuestions" :key="question.label"><dt>{{ question.label }}</dt><dd>{{ question.value }}</dd></div><div v-if="!values.reporter.isPassenger"><dt>הקשר שלכם לאירוע</dt><dd>{{ values.reporter.relationship }}</dd></div></dl></details>
              <div class="report-privacy-summary"><h3>לפני שאתם שולחים</h3><p>המידע נועד לבחינת דיווחים, למחקר, לאיתור דפוסים צרכניים ולבחינת צעדים מתאימים. פרטי הקשר אינם מתפרסמים אוטומטית. אין התחייבות לטיפול אישי, לייצוג או לפיצוי.</p><p><RouterLink to="/privacy" target="_blank" rel="noopener">הודעת הפרטיות המלאה</RouterLink> · <RouterLink to="/terms" target="_blank" rel="noopener">תנאי השימוש</RouterLink></p><span class="report-draft-label">נוסחי הפרטיות וההסכמות הם טיוטה הטעונה אישור משפטי לפני הפעלה לציבור.</span></div>
              <div class="report-consents"><label class="report-consent" :class="{invalid:errorAt('consents.privacy')}"><input v-model="values.consents.privacy" type="checkbox" :aria-invalid="!!errorAt('consents.privacy')" :aria-describedby="errorAt('consents.privacy')?'consents.privacy-error':undefined" /><span><strong>קראתי את הודעת הפרטיות, והמידע שמסרתי נכון למיטב ידיעתי.</strong><small>אישור נדרש לשליחת הדיווח · נוסח טיוטה לאישור משפטי.</small></span></label><p v-if="errorAt('consents.privacy')" id="consents.privacy-error" class="field-error" role="alert">{{ errorAt('consents.privacy') }}</p><label class="report-consent"><input v-model="values.consents.caseContact" type="checkbox" /><span>אני מסכים/ה ליצירת קשר לצורך הטיפול בדיווח שלי.<small>רשות · ההסכמה מאפשרת פנייה אליכם לצורך בירור פרטי המקרה והטיפול בדיווח.</small></span></label><label class="report-consent"><input v-model="values.consents.updates" type="checkbox" /><span>אני מסכים/ה לקבל עדכונים ודיוור, אם הארגון יפעיל שירות כזה.<small>רשות · הסכמה נפרדת שאינה תנאי לשליחת הדיווח.</small></span></label></div>
            </template>
          </div>
          <div class="report-form-actions"><button v-if="step>0" class="btn btn-ghost" type="button" :disabled="submitting" @click="goTo(step-1)"><ArrowRight :size="17" />חזרה</button><span v-else class="report-form-saving"><ShieldCheck :size="15" />ממלאים בקצב שלכם</span><button v-if="step<steps.length-1" class="btn btn-primary" type="button" @click="next">המשך לשלב הבא<ArrowLeft :size="17" /></button><button v-else class="btn btn-primary" type="submit" :disabled="submitting||!config" :aria-busy="submitting">{{ submitting?'שולחים את הדיווח…':'שליחת הדיווח' }}<ArrowLeft v-if="!submitting" :size="17" /></button></div>
        </form><p class="report-session-note">הפרטים נשארים בטופס כל עוד העמוד פתוח. סגירה או רענון של העמוד ימחקו את הטיוטה.</p>
      </div>
      <aside class="report-help"><span class="report-help-icon"><CircleHelp :size="23" /></span><h3>טוב לדעת</h3><p>{{ currentStep.help }}</p><div class="report-help-divider" /><ShieldCheck :size="20" /><strong>הפרטים שלכם חשובים.</strong><p>הארגון אינו מקבל מסמכים. מסרו רק מידע הנחוץ להבנת המקרה. הדיווחים נגישים לצוות מורשה בלבד.</p><RouterLink to="/privacy">איך מטפלים במידע?<ArrowLeft :size="14" /></RouterLink></aside>
    </div>
  </main>
</template>

